import { Suspense } from "react"

import { LiveRefresh } from "@/components/live-refresh"
import { UsbAttendanceProvider, UsbAttendanceReader } from "@/components/usb-attendance-reader"
import { MonitoringDateFilter } from "@/app/(portal)/admin/live-monitoring/components/monitoring-date-filter"
import { MonitoringPanelSkeleton } from "@/app/(portal)/admin/live-monitoring/components/monitoring-panel-skeleton"

export const dynamic = "force-dynamic"

async function SlowPanel({ from, to }: { from: string; to: string }) {
  await new Promise(resolve => setTimeout(resolve, 4000))
  return <p>Panel {from} to {to}</p>
}

export default async function DebugFullPage({ searchParams }: { searchParams: Promise<{ from?: string; to?: string }> }) {
  const params = await searchParams
  const from = params.from ?? "2026-10-22"
  const to = params.to ?? "2026-10-28"

  return (
    <UsbAttendanceProvider>
      <div className="@container/main flex flex-1 flex-col gap-4 p-4 md:gap-6 md:p-6">
        <LiveRefresh channel="live-admin-monitoring" tables={["attendance_records", "students", "programs", "rfid_cards"]} debounceMs={300} />
        <div className="space-y-1">
          <h1 className="text-2xl font-semibold tracking-tight text-balance">Live Monitoring</h1>
        </div>
        <UsbAttendanceReader />
        <MonitoringDateFilter key={`${from}:${to}`} from={from} to={to} />
        <Suspense fallback={<MonitoringPanelSkeleton />}>
          <SlowPanel from={from} to={to} />
        </Suspense>
      </div>
    </UsbAttendanceProvider>
  )
}
